<?php
require_login();
$assessmentId = (int)($_GET['id'] ?? $_POST['assessment_id'] ?? 0);
$stmt = db()->prepare('SELECT * FROM assessments WHERE id=? AND user_id=?');
$stmt->execute([$assessmentId, user()['id']]);
$assessment = $stmt->fetch();
if (!$assessment) { http_response_code(404); exit('Không tìm thấy bài đánh giá.'); }
if (is_post()) {
    verify_csrf();
    if (!empty($assessment['ai_generated_at']) && time() - strtotime((string)$assessment['ai_generated_at']) < 180) { flash('warning', 'Vui lòng đợi 3 phút giữa các lần tạo tư vấn AI.'); redirect('index.php?page=result&id='.$assessmentId); }
    $allowed = ['budget'=>['0','1','2','3','unknown'],'study_path'=>['any','university','college','vocational'],'study_years'=>['any','short','long'],'activity'=>['any','low','medium','high'],'pushups'=>['skip','0-4','5-9','10-19','20-plus'],'pullups'=>['skip','0','1-2','3-5','6-plus'],'run'=>['skip','under-1','1-3','3-5','5-plus'],'scholarship'=>['yes','no','unknown'],'portfolio'=>['yes','no','unknown']];
    $answers = [];
    foreach ($allowed as $key=>$choices) { $value = !empty($_POST['skip_survey']) ? ($key === 'budget' || $key === 'scholarship' || $key === 'portfolio' ? 'unknown' : ($key === 'pushups' || $key === 'pullups' || $key === 'run' ? 'skip' : 'any')) : (string)($_POST[$key] ?? ''); if (!in_array($value, $choices, true)) { http_response_code(422); exit('Một hoặc nhiều câu trả lời không hợp lệ.'); } $answers[$key] = $value; }
    unset($answers['pushups'], $answers['pullups'], $answers['run']);
    $matches = career_matches(json_decode($assessment['scores'], true) ?: [], 6, $answers);
    db()->beginTransaction();
    try {
        $save = db()->prepare('UPDATE assessments SET constraint_answers=?,ai_advice=NULL,ai_status=\'pending\',ai_model=NULL,ai_error=NULL,ai_generated_at=NULL WHERE id=? AND user_id=?');
        $save->execute([json_encode($answers, JSON_UNESCAPED_UNICODE), $assessmentId, user()['id']]);
        db()->prepare('DELETE FROM assessment_matches WHERE assessment_id=?')->execute([$assessmentId]);
        $insert = db()->prepare('INSERT INTO assessment_matches(assessment_id,career_id,match_percent,rank_order) VALUES(?,?,?,?)');
        foreach ($matches as $i=>$career) $insert->execute([$assessmentId, $career['id'], $career['match_percent'], $i+1]);
        db()->commit();
    } catch (Throwable $e) { if (db()->inTransaction()) db()->rollBack(); throw $e; }
    generate_assessment_ai($assessmentId, (int)user()['id']);
    audit('Hoàn thành khảo sát điều kiện hướng nghiệp', 'assessment', $assessmentId);
    redirect('index.php?page=result&id='.$assessmentId);
}
$pageTitle = 'Điều kiện học tập và công việc';
require __DIR__.'/header.php';
?>
